def is_good(m):
    s = str(m)
    if len(s) == 1:
        return True

    # Check distinct nonzero digits
    if len(set(s)) != len(s) or '0' in s:
        return False

    # Check if removing one digit results in a divisor that is also good
    for i in range(len(s)):
        s_prime = s[:i] + s[i+1:]
        m_prime = int(s_prime)
        if m % m_prime == 0:
            if is_good(m_prime):
                return True
    return False

