            s_prime = str(m_prime)
            digits_prime = set(s_prime)
            for d in "123456789":
                if d not in digits_prime:
                    for i in range(len(s_prime) + 1):
                        s = s_prime[:i] + d + s_prime[i:]
                        m = int(s)
                        if m % m_prime == 0:
                            next_len_good.add(m)

        if not next_len_good:
            break

        all_good.update(next_len_good)
        current_len_good = next_len_good

